import json, subprocess, sys
def gh(args):
    r = subprocess.run(["gh", "api"] + args, capture_output=True, text=True)
    if r.returncode != 0:
        return None
    return json.loads(r.stdout)
found = []
checked = 0
for page in range(1, 4):
    res = gh(["-X", "GET", "search/issues", "-f", "q=is:issue is:blocked is:public", "-f", "per_page=100", "-f", f"page={page}"])
    if not res:
        break
    for it in res["items"]:
        owner = it["repository_url"].split("/")[-2]
        repo = it["repository_url"].split("/")[-1]
        deps = gh([f"repos/{owner}/{repo}/issues/{it['number']}/dependencies/blocked_by"])
        checked += 1
        if not deps:
            continue
        for d in deps:
            downer = d["repository_url"].split("/")[-2]
            drepo = d["repository_url"].split("/")[-1]
            if downer.lower() != owner.lower():
                found.append((f"{owner}/{repo}#{it['number']}", f"{downer}/{drepo}#{d['number']}", d.get("state")))
            elif drepo.lower() != repo.lower():
                found.append((f"{owner}/{repo}#{it['number']}", f"{downer}/{drepo}#{d['number']} (same owner, other repo)", d.get("state")))
        if len([f for f in found if "same owner" not in f[1]]) >= 3:
            break
    if len([f for f in found if "same owner" not in f[1]]) >= 3:
        break
print("checked", checked)
for f in found[:20]:
    print(f)
EOF
